/* Generated from web/tour.json. */
window.TourContent={"duas":{"niyyah":{"ar":"لَبَّيْكَ اللَّهُمَّ عُمْرَةً","tr":"Labbayka Allāhumma ʿumrah","en":"Here I am, O Allah, for Umrah.","review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[]},"ishtirat":{"ar":"اللَّهُمَّ مَحِلِّي حَيْثُ حَبَسْتَنِي","tr":"Allāhumma maḥillī ḥaythu ḥabastanī","en":"O Allah, I will leave ihram wherever You hold me back.","src":{"en":"Hadith, Bukhari & Muslim","ar":"حديث، رواه البخاري ومسلم"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[{"label":"Sahih Muslim 1207a","url":"https://sunnah.com/muslim:1207a"}]},"talbiyah":{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ","tr":"Labbayka Allāhumma labbayk, labbayka lā sharīka laka labbayk, inna l-ḥamda wa n-niʿmata laka wa l-mulk, lā sharīka lak","en":"Here I am, O Allah, here I am. Here I am, You have no partner, here I am. All praise, all blessings and all sovereignty belong to You. You have no partner.","src":{"en":"Hadith, Bukhari & Muslim","ar":"حديث، رواه البخاري ومسلم"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[{"label":"Sahih Muslim 1184a","url":"https://sunnah.com/muslim:1184a"}]},"enter":{"ar":"بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"Bismillāh, waṣ-ṣalātu was-salāmu ʿalā rasūlillāh, Allāhumma ftaḥ lī abwāba raḥmatik","en":"In the name of Allah, and peace and blessings be upon the Messenger of Allah. O Allah, open for me the gates of Your mercy.","src":{"en":"Hadith, Muslim & Ibn Majah","ar":"حديث، رواه مسلم وابن ماجه"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review. The linked Muslim narration supports the final clause; the opening composite wording requires separate verification."},"references":[{"label":"Sahih Muslim 713a (gates of mercy)","url":"https://sunnah.com/muslim:713a"}]},"bismillah":{"ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ","tr":"Bismillāh, wallāhu akbar","en":"In the name of Allah, Allah is the Greatest.","src":{"en":"Ibn Umar at the Black Stone, Ahmad & al-Bayhaqi","ar":"أثر ابن عمر عند استلام الحجر، رواه أحمد والبيهقي"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[]},"rabbana":{"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","tr":"Rabbanā ātinā fid-dunyā ḥasanatan wa fil-ākhirati ḥasanatan wa qinā ʿadhāban-nār","en":"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.","src":{"en":"Quran 2:201","ar":"سورة البقرة، الآية ٢٠١"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[{"label":"Quran 2:201","url":"https://quran.com/2/201"},{"label":"Hisn al-Muslim 235","url":"https://sunnah.com/hisn:235"}]},"maqam":{"ar":"وَاتَّخِذُوا مِن مَّقَامِ إِبْرَاهِيمَ مُصَلًّى","tr":"Wattakhidhū min maqāmi Ibrāhīma muṣallā","en":"And take the station of Ibrahim as a place of prayer.","src":{"en":"Quran 2:125","ar":"سورة البقرة، الآية ١٢٥"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[{"label":"Quran 2:125","url":"https://quran.com/2/125"},{"label":"Sahih Muslim 1218a","url":"https://sunnah.com/muslim:1218a"}]},"safa_verse":{"ar":"إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ — أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ","tr":"Innaṣ-Ṣafā wal-Marwata min shaʿāʾirillāh — abdaʾu bimā badaʾa Allāhu bih","en":"Indeed, Safa and Marwah are among the symbols of Allah. I begin with what Allah began with.","src":{"en":"Quran 2:158, then hadith of Jabir (Muslim)","ar":"سورة البقرة، الآية ١٥٨، ثم حديث جابر (مسلم)"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[{"label":"Quran 2:158","url":"https://quran.com/2/158"},{"label":"Sahih Muslim 1218a","url":"https://sunnah.com/muslim:1218a"}]},"safa_dhikr":{"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ","tr":"Lā ilāha illā Allāhu waḥdahu lā sharīka lah, lahul-mulku wa lahul-ḥamd, wa huwa ʿalā kulli shayʾin qadīr. Lā ilāha illā Allāhu waḥdah, anjaza waʿdah, wa naṣara ʿabdah, wa hazamal-aḥzāba waḥdah","en":"There is no god but Allah alone, without partner. His is the dominion and the praise, and He has power over all things. There is no god but Allah alone. He fulfilled His promise, gave victory to His servant, and alone defeated the confederates.","src":{"en":"Hadith of Jabir, Muslim","ar":"حديث جابر، رواه مسلم"},"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Exact wording, translation, recitation and supporting references await scholarly review."},"references":[{"label":"Sahih Muslim 1218a","url":"https://sunnah.com/muslim:1218a"}]}},"labels":{"kaaba":{"en":"Kaaba","ar":"الكعبة"},"black_stone":{"en":"Black Stone","ar":"الحجر الأسود"},"yemeni":{"en":"Yemeni Corner","ar":"الركن اليماني"},"door":{"en":"Door of the Kaaba","ar":"باب الكعبة"},"hijr":{"en":"Hijr Ismail","ar":"حِجر إسماعيل"},"mizab":{"en":"Golden waterspout","ar":"الميزاب"},"maqam":{"en":"Maqam Ibrahim","ar":"مقام إبراهيم"},"start_light":{"en":"Green start light","ar":"ضوء البداية الأخضر"},"clock":{"en":"Clock tower","ar":"برج الساعة"},"zamzam":{"en":"Zamzam water","ar":"ماء زمزم"},"gate":{"en":"Gates","ar":"الأبواب"},"safa_rock":{"en":"Hill of Safa","ar":"جبل الصفا"},"marwa_rock":{"en":"Hill of Marwah","ar":"جبل المروة"},"to_marwa":{"en":"Towards Marwah","ar":"نحو المروة"},"to_safa":{"en":"Towards Safa","ar":"نحو الصفا"},"green_lights":{"en":"Green lights","ar":"الأضواء الخضراء"},"green_end":{"en":"End of green lights","ar":"نهاية الأضواء الخضراء"}},"stations":[{"id":"ihram","pano":"entry","card":true,"labels":[],"title":{"en":"Entering ihram at the Miqat","ar":"الإحرام من الميقات"},"place":{"en":"Before you arrive","ar":"قبل الوصول"},"steps":[{"look":"kaaba","fov":95,"illus":"prep","en":"Before you reach the Miqat, the boundary where ihram begins, take a full bath and trim your nails. Men may perfume their body, but not their clothes.","ar":"قبل أن تصل إلى الميقات، وهو الحدّ الذي يبدأ منه الإحرام، اغتسل وقلّم أظافرك. ويجوز للرجل أن يتطيّب في بدنه دون ثيابه."},{"look":"kaaba","fov":95,"illus":"clothes","en":"Men wear two white unstitched cloths and sandals. Women wear their usual modest clothes, with the face and hands uncovered.","ar":"يلبس الرجل إزارًا ورداءً أبيضين غير مخيطين، ونعلين. وتلبس المرأة ثيابها المحتشمة المعتادة، مع كشف الوجه والكفّين."},{"look":"kaaba","fov":95,"dua":"niyyah","illus":"niyyah","en":"At the Miqat, make your intention for Umrah. If you are flying, the crew announces the Miqat, so be ready before take-off.","ar":"عند الميقات، انوِ العمرة. وإن كنت مسافرًا بالطائرة، فإن الطاقم يعلن عن الميقات، فكن مستعدًّا قبل الإقلاع."},{"look":"kaaba","fov":95,"dua":"ishtirat","illus":"ishtirat","en":"If you fear that illness may stop you, you may add this condition. It is a mercy for older and sick pilgrims.","ar":"إن خشيت أن يمنعك مرض من إتمام العمرة، فلك أن تشترط هذا الشرط. وهو تيسير لكبار السن والمرضى."},{"look":"kaaba","fov":95,"dua":"talbiyah","illus":"talbiyah","en":"Now repeat the Talbiyah often until you reach the Kaaba. Men say it aloud, women softly.","ar":"ثم أكثِر من التلبية حتى تصل إلى الكعبة. يرفع بها الرجال أصواتهم، وتخفضها النساء."},{"look":"kaaba","fov":95,"illus":"avoid","en":"While in ihram, avoid perfume, cutting hair or nails, and marital relations. Men do not cover their head.","ar":"وفي الإحرام اجتنب الطيب، وأخذ شيء من الشعر أو الأظافر، والجماع. ولا يغطّي الرجل رأسه."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"enter","pano":"entry","labels":["kaaba","zamzam","gate"],"title":{"en":"Entering the Haram","ar":"دخول المسجد الحرام"},"place":{"en":"Masjid al-Haram","ar":"المسجد الحرام"},"steps":[{"look":"gate","fov":85,"en":"Every gate of the Haram has a number and a name. Note them down or take a photo before you enter. This is your meeting point if you are separated from your group.","ar":"لكل باب من أبواب الحرم رقم واسم. دوّنهما أو التقط لهما صورة قبل الدخول، فهذا مكان لقائك إن افترقت عن مجموعتك."},{"look":"kaaba","fov":85,"dua":"enter","en":"Enter with your right foot first and say the supplication for entering the mosque.","ar":"ادخل برجلك اليمنى، وقل دعاء دخول المسجد."},{"look":"kaaba","fov":45,"en":"This is the Kaaba. Take your time. Make any supplication you wish, in your own language.","ar":"هذه هي الكعبة المشرّفة. تمهّل، وادعُ بما شئت، وبلغتك أنت."},{"look":"zamzam","fov":75,"en":"Zamzam water is available in coolers all around the mosque. Drink and rest whenever you need. Umrah has no time limit.","ar":"ماء زمزم متوفّر في برّادات حول المسجد كله. اشرب واسترح متى احتجت، فليس للعمرة وقت محدّد."},{"look":"kaaba","fov":70,"en":"Make sure you have wudu before Tawaf. Stop saying the Talbiyah when you begin.","ar":"تأكّد أنك على وضوء قبل الطواف، واقطع التلبية عند بدء الطواف."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"start","pano":"start","counter":"tawaf","labels":["black_stone","door","start_light","maqam"],"title":{"en":"Starting Tawaf at the Black Stone","ar":"بدء الطواف عند الحجر الأسود"},"place":{"en":"Tawaf · the Mataf","ar":"الطواف – صحن المطاف"},"steps":[{"look":"black_stone","dpitch":6,"fov":55,"en":"Walk to the corner of the Kaaba with the Black Stone, set in a silver frame. Tawaf starts and ends here.","ar":"توجّه إلى ركن الكعبة الذي فيه الحجر الأسود، في إطاره الفضّي. من هنا يبدأ الطواف وإليه ينتهي."},{"look":"start_light","fov":70,"en":"Behind you, a green light on the mosque wall marks the starting line. Use it to see where each circuit begins.","ar":"خلفك ضوء أخضر على جدار المسجد يحدّد خطّ البداية. استعن به لتعرف أين يبدأ كل شوط."},{"look":"black_stone","dpitch":6,"fov":55,"dua":"bismillah","en":"Men uncover the right shoulder for this Tawaf. Face the Black Stone, raise your right hand towards it, and say these words. Do not push to kiss or touch it. Pointing is enough.","ar":"يكشف الرجل كتفه الأيمن في هذا الطواف. استقبل الحجر الأسود، وأشر إليه بيدك اليمنى، وقل هذه الكلمات. ولا تزاحم لتقبيله أو لمسه، فالإشارة تكفي."},{"look":"kaaba","dyaw":25,"fov":85,"en":"Now walk counter-clockwise, keeping the Kaaba on your left. Men walk briskly in the first three circuits if they are able.","ar":"والآن طُف عكس اتجاه عقارب الساعة، والكعبة عن يسارك. ويُسرع الرجال في الأشواط الثلاثة الأولى إن استطاعوا."},{"look":"door","fov":60,"en":"You will pass the door of the Kaaba, behind a gold-embroidered curtain. There is no fixed supplication for each circuit. Make dua, remember Allah, or recite Quran, in any language.","ar":"ستمرّ بباب الكعبة خلف ستارة مطرّزة بالذهب. ليس لكل شوط دعاء مخصوص، فادعُ واذكر الله أو اقرأ القرآن، بأي لغة."},{"look":"black_stone","dpitch":6,"fov":70,"highlight":"counter","en":"Each time you come back to the Black Stone line, one circuit is complete. Tap the counter so you never lose count.","ar":"كلما عدت إلى خط الحجر الأسود اكتمل شوط. اضغط على العدّاد حتى لا يفوتك العدد."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"hijr","pano":"hijr","counter":"tawaf","labels":["hijr","mizab","kaaba"],"title":{"en":"Around the Hijr Ismail","ar":"حول حِجر إسماعيل"},"place":{"en":"Tawaf · north-west side","ar":"الطواف – الجهة الشمالية الغربية"},"steps":[{"look":"hijr","dpitch":4,"fov":70,"en":"This low, curved wall is the Hijr Ismail. The area inside is part of the Kaaba, so walk around the outside of the wall.","ar":"هذا الجدار المنخفض المقوّس هو حِجر إسماعيل. وما بداخله من الكعبة، فطُف من خارج الجدار."},{"look":"mizab","fov":50,"en":"Above it, the golden waterspout carries rainwater from the roof of the Kaaba.","ar":"وفوقه الميزاب الذهبي الذي ينزل منه ماء المطر من سطح الكعبة."},{"look":"kaaba","dyaw":-60,"fov":90,"en":"If you are tired, move towards the outer part of the courtyard or to an upper floor. The circuits are longer, but the crowd is lighter.","ar":"إن شعرت بالتعب، فابتعد نحو أطراف الصحن أو اصعد إلى أحد الطوابق. الأشواط أطول، لكن الزحام أخفّ."},{"look":"kaaba","fov":80,"en":"If you lose your group, do not stop or walk against the crowd. Finish your circuit and go to your meeting gate.","ar":"إن فقدت مجموعتك، فلا تتوقّف ولا تمشِ عكس الزحام. أكمل شوطك ثم اذهب إلى باب اللقاء."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"yemeni","pano":"yemeni","counter":"tawaf","labels":["yemeni","black_stone","clock"],"title":{"en":"The Yemeni Corner","ar":"الركن اليماني"},"place":{"en":"Tawaf · south side","ar":"الطواف – الجهة الجنوبية"},"steps":[{"look":"yemeni","dpitch":6,"fov":55,"en":"This is the Yemeni Corner, the last corner before the Black Stone. Touch it with your right hand only if it is easy. If you cannot, simply walk on, without pointing.","ar":"هذا هو الركن اليماني، آخر ركن قبل الحجر الأسود. المسه بيدك اليمنى إن تيسّر، وإلا فامضِ دون إشارة."},{"look":"black_stone","dyaw":-8,"dpitch":8,"fov":65,"dua":"rabbana","en":"Between the Yemeni Corner and the Black Stone, say this verse.","ar":"وبين الركن اليماني والحجر الأسود قل هذه الآية."},{"look":"clock","dpitch":-25,"fov":95,"en":"The tall clock tower stands behind this side of the mosque. It helps you find your direction from almost anywhere.","ar":"برج الساعة الشاهق يقع خلف هذه الجهة من المسجد، ويساعدك على معرفة الاتجاه من أي مكان تقريبًا."},{"look":"black_stone","dpitch":6,"fov":70,"highlight":"counter","en":"Continue until you complete seven circuits, ending at the Black Stone. Then men cover their right shoulder again.","ar":"أكمل سبعة أشواط تنتهي عند الحجر الأسود، ثم يغطّي الرجال كتفهم الأيمن."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"maqam","pano":"maqam","labels":["maqam","kaaba","zamzam"],"title":{"en":"Prayer at Maqam Ibrahim","ar":"الصلاة عند مقام إبراهيم"},"place":{"en":"After Tawaf","ar":"بعد الطواف"},"steps":[{"look":"maqam","fov":55,"dua":"maqam","en":"This golden structure is the Maqam Ibrahim, the station of the Prophet Ibrahim. Go behind it and recite this verse.","ar":"هذا البناء الذهبي هو مقام إبراهيم عليه السلام. قف خلفه واقرأ هذه الآية."},{"look":"kaaba","fov":70,"en":"Pray two short rak’ahs. It is recommended to recite Al-Kafirun in the first and Al-Ikhlas in the second. If it is crowded, pray anywhere in the mosque.","ar":"صلِّ ركعتين خفيفتين، ويُستحب أن تقرأ في الأولى سورة الكافرون وفي الثانية سورة الإخلاص. وإن كان المكان مزدحمًا فصلِّ في أي مكان من المسجد."},{"look":"zamzam","fov":80,"en":"Then drink Zamzam water and ask Allah for whatever you wish.","ar":"ثم اشرب من ماء زمزم، وادعُ الله بما تشاء."},{"look":"kaaba","dyaw":-40,"fov":90,"en":"Next comes the Sa’i. Follow the signs to the Mas’a and the hill of Safa.","ar":"بعد ذلك يأتي السعي. اتبع اللوحات المؤدية إلى المسعى وجبل الصفا."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"safa","pano":"safa","counter":"sai","labels":["safa_rock","to_marwa"],"title":{"en":"Beginning Sa’i at Safa","ar":"بدء السعي من الصفا"},"place":{"en":"Sa’i · the Mas’a","ar":"السعي – المسعى"},"steps":[{"look":"safa_rock","fov":70,"dua":"safa_verse","en":"This rock is the hill of Safa, where Sa’i begins. As you approach it the first time, recite this.","ar":"هذه الصخرة هي جبل الصفا، ومنه يبدأ السعي. وعند اقترابك منه أول مرة اقرأ هذا."},{"look":"safa_rock","dpitch":10,"fov":80,"dua":"safa_dhikr","en":"Face the direction of the Kaaba and raise your hands as in supplication. Say Allahu Akbar three times, then these words. Repeat three times, with your own dua in between.","ar":"استقبل جهة الكعبة، وارفع يديك كهيئة الدعاء. كبّر ثلاثًا، ثم قل هذا الذكر. كرّره ثلاث مرات، وادعُ بما شئت بينها."},{"look":"to_marwa","fov":80,"en":"Now walk towards Marwah. Keep to the lane going in your direction and follow the signs above you.","ar":"والآن امشِ نحو المروة. الزم المسار الخاص باتجاهك واتبع اللوحات فوقك."},{"look":"to_marwa","dyaw":-30,"dpitch":-8,"fov":85,"en":"Sa’i does not require wudu, and you may stop to rest. If walking is difficult, you may use a wheelchair.","ar":"لا يُشترط الوضوء للسعي، ويجوز لك أن تستريح. وإن صعب عليك المشي فلك أن تستعمل كرسيًّا متحرّكًا."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"green","pano":"green","counter":"sai","labels":["green_lights","to_marwa"],"title":{"en":"Between the green lights","ar":"بين العلمين الأخضرين"},"place":{"en":"Sa’i · middle section","ar":"السعي – المنتصف"},"steps":[{"look":"green_lights","fov":80,"en":"These green lights mark the stretch where Hajar ran in search of water for her son Ismail.","ar":"هذه الأضواء الخضراء تحدّد المسافة التي سعت فيها هاجر بحثًا عن الماء لابنها إسماعيل."},{"look":"to_marwa","dpitch":-6,"fov":85,"en":"Men walk quickly between the green lights if they are able. Women walk at their normal pace.","ar":"يُسرع الرجال بين الضوءين الأخضرين إن استطاعوا، وتمشي النساء مشيًا عاديًّا."},{"look":"to_marwa","dyaw":40,"fov":85,"en":"There is no fixed supplication here. Ask Allah for whatever you need, in your own words.","ar":"ليس هنا دعاء مخصوص، فاسأل الله ما تحتاج بكلماتك أنت."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"marwa","pano":"marwa","counter":"sai","labels":["marwa_rock","to_safa"],"title":{"en":"Arriving at Marwah","ar":"الوصول إلى المروة"},"place":{"en":"Sa’i · the Mas’a","ar":"السعي – المسعى"},"steps":[{"look":"marwa_rock","fov":70,"dua":"safa_dhikr","en":"This is Marwah. Reaching it completes one length. Face the Kaaba and repeat the same remembrance as at Safa, without the verse.","ar":"هذه هي المروة. ببلوغها يكتمل شوط واحد. استقبل الكعبة وكرّر الذكر نفسه الذي قلته على الصفا، دون الآية."},{"look":"to_safa","fov":80,"en":"Returning to Safa is length two. Seven lengths in total, Safa to Marwah and back, ending here at Marwah.","ar":"والعودة إلى الصفا شوط ثانٍ. والمجموع سبعة أشواط بين الصفا والمروة، تنتهي هنا عند المروة."},{"look":"marwa_rock","dyaw":30,"fov":85,"highlight":"counter","en":"Use the counter. Tap once each time you reach a hill.","ar":"استعمل العدّاد، واضغط مرة واحدة كلما بلغت أحد الجبلين."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}},{"id":"done","pano":"marwa","card":true,"labels":[],"title":{"en":"Shaving or shortening the hair","ar":"الحلق أو التقصير"},"place":{"en":"End of Umrah","ar":"نهاية العمرة"},"steps":[{"look":"marwa_rock","fov":90,"illus":"halq","en":"Men shave the whole head, which is best, or shorten the hair evenly. Women cut about a fingertip’s length from the end of their hair.","ar":"يحلق الرجل رأسه كله، وهو الأفضل، أو يقصّر شعره من جميع رأسه. وتقصّ المرأة من أطراف شعرها قدر أنملة."},{"look":"marwa_rock","fov":90,"illus":"complete","en":"Your Umrah is complete, and the restrictions of ihram are lifted. May Allah accept it from you.","ar":"وبهذا تمّت عمرتك، وحلّ لك ما كان محظورًا في الإحرام. تقبّل الله منك."}],"review":{"status":"pending","reviewer":null,"reviewedAt":null}}],"schemaVersion":1,"review":{"status":"pending","reviewer":null,"reviewedAt":null,"notes":"Prototype content. Scholarly and recitation review remain outstanding."},"practice":{"missions":[{"id":"enter","scene":"haram","title":{"en":"Enter the Haram","ar":"ادخل المسجد الحرام"},"goal":{"en":"Walk into the open courtyard around the Kaaba (the Mataf).","ar":"امشِ إلى الصحن المكشوف حول الكعبة (المطاف)."},"audio":["n:enter_1","d:enter"]},{"id":"stone","title":{"en":"Go to the Black Stone","ar":"توجّه إلى الحجر الأسود"},"goal":{"en":"Stand on the green start line, facing the Black Stone corner.","ar":"قف على خط البداية الأخضر مستقبلًا ركن الحجر الأسود."},"audio":["n:enter_2","n:enter_4","n:start_0"]},{"id":"tawaf","title":{"en":"Tawaf: 7 circuits","ar":"الطواف: سبعة أشواط"},"goal":{"en":"Walk around the Kaaba keeping it on your left. Each return to the green line is one circuit.","ar":"طُف حول الكعبة وهي عن يسارك. كل عودة إلى الخط الأخضر شوط."},"audio":["n:start_2","d:bismillah","n:start_3"]},{"id":"maqam","title":{"en":"Pray behind Maqam Ibrahim","ar":"صلِّ خلف مقام إبراهيم"},"goal":{"en":"Go behind the golden Maqam and pray two short rak‘ahs.","ar":"قف خلف المقام الذهبي وصلِّ ركعتين خفيفتين."},"audio":["d:maqam","n:maqam_1"]},{"id":"zamzam","title":{"en":"Drink Zamzam water","ar":"اشرب من ماء زمزم"},"goal":{"en":"Find a Zamzam cooler at the edge of the courtyard.","ar":"اذهب إلى أحد برّادات زمزم عند أطراف الصحن."},"audio":["n:maqam_2"]},{"id":"masa","title":{"en":"Go to the Mas‘a","ar":"اذهب إلى المسعى"},"goal":{"en":"Walk under the arcades to the green Mas‘a sign.","ar":"امشِ تحت الأروقة إلى لوحة المسعى الخضراء."},"audio":["n:maqam_3"]},{"id":"safa","scene":"masa","title":{"en":"At Safa","ar":"على الصفا"},"goal":{"en":"Face the Kaaba, raise your hands, and remember Allah. Then begin.","ar":"استقبل الكعبة وارفع يديك واذكر الله، ثم ابدأ."},"audio":["n:safa_0","d:safa_verse","n:safa_1","d:safa_dhikr"]},{"id":"sai","title":{"en":"Sa‘i: 7 lengths","ar":"السعي: سبعة أشواط"},"goal":{"en":"Walk to Marwah and back. Seven lengths in total, ending at Marwah.","ar":"امشِ إلى المروة ثم عُد. سبعة أشواط تنتهي عند المروة."},"audio":["n:safa_2"]}],"dhikr":[["سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ","Subḥān Allāh, wal-ḥamdu lillāh, wa lā ilāha illā Allāh, wallāhu akbar","Glory be to Allah, praise be to Allah, there is no god but Allah, and Allah is the Greatest."],["أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","Astaghfirullāha wa atūbu ilayh","I seek Allah’s forgiveness and turn to Him in repentance."],["لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","Lā ḥawla wa lā quwwata illā billāh","There is no power and no strength except with Allah."],["اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ","Allāhumma ṣalli wa sallim ʿalā nabiyyinā Muḥammad","O Allah, send prayers and peace upon our Prophet Muhammad."],["رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ","Rabbighfir lī wa li-wālidayya","My Lord, forgive me and my parents."],["اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","Allāhumma innaka ʿafuwwun tuḥibbul-ʿafwa faʿfu ʿannī","O Allah, You are the Pardoner and You love to pardon, so pardon me."]],"tawafScript":{"0":[[0.06,"n:start_4"],[0.3,"n:hijr_0"],[0.42,"n:hijr_1"],[0.66,"n:yemeni_0"]],"1":[[0.12,"n:start_1"],[0.45,"dhikr:0"]],"2":[[0.15,"n:yemeni_2"],[0.45,"dhikr:1"]],"3":[[0.15,"n:hijr_2"],[0.45,"dhikr:2"]],"4":[[0.15,"n:hijr_3"],[0.45,"dhikr:3"]],"5":[[0.15,"n:enter_3"],[0.45,"dhikr:4"]],"6":[[0.15,"n:yemeni_3"],[0.45,"dhikr:5"]]},"saiScript":[[0,70,"n:green_0"],[1,340,"n:marwa_1"],[2,60,"n:safa_3"],[3,330,"n:green_2"],[4,90,"dhikr:0"],[5,300,"dhikr:2"],[6,90,"dhikr:5"]],"text":{"en":{"intro":"Umrah in 3D","introText":"Explore the Haram and Mas‘a at your own pace, or tap “Guide me”.","loading":"Loading the Haram…","ready":"Ready.","start":"I am in ihram, begin","note":"Simplified real-time 3D for orientation, not an exact model. Duas from Hisn al-Muslim; Quran recitation by Mishary Rashid Alafasy.","niyyah":"At the Miqat, make your intention:","talbiyah":"Then repeat the Talbiyah:","listen":"Listen","stop":"Stop","ok":"Continue","guide":"Guide me","guiding":"Guiding…","run":"Run","day":"Day","night":"Night","tour":"Guided tour","mission":"Mission","of":"of","m":"m away","beginSai":"Begin Sa‘i","skipTawaf":"Fast-forward remaining circuits","skipSai":"Fast-forward remaining lengths","wrongWay":"Wrong direction","wrongWayText":"Keep the Kaaba on your left. Turn around and walk the other way.","hijr":"This circuit does not count","hijrText":"The Hijr Ismail is part of the Kaaba. Walk around the outside of its curved wall.","green":"Green lights: men walk quickly here, women at their normal pace.","doneTitle":"Your Umrah is complete","doneText":"Men shave the head or shorten the hair; women cut a fingertip’s length. May Allah accept it from you.","again":"Start again","back":"Back to the guided tour","entering":"Entering the Mas‘a…","rabbana":"Between the Yemeni Corner and the Black Stone","soundOn":"Sound on","soundOff":"Sound off","takbir":"At the Black Stone line","dhikr":"Remember Allah","arriveSafa":"At Safa","arriveMarwa":"At Marwah","noWebgl":"This device cannot show 3D (WebGL2 is not available).","how":["Move: W A S D or arrow keys. Look: drag with the mouse (double-click to lock it, Esc to release).","Phone: drag on the left to walk, on the right to look.","“Guide me” walks you through the current mission, then hands control back. “Run” goes faster."]},"ar":{"intro":"العمرة ثلاثية الأبعاد","introText":"استكشف المسجد الحرام والمسعى بنفسك، أو اضغط «أرشدني».","loading":"جارٍ تحميل المسجد الحرام…","ready":"جاهز.","start":"أنا محرم، ابدأ","note":"مشهد ثلاثي الأبعاد مبسّط للمساعدة على التوجّه، وليس نموذجًا دقيقًا. الأدعية من حصن المسلم، والتلاوة بصوت مشاري راشد العفاسي.","niyyah":"عند الميقات انوِ العمرة:","talbiyah":"ثم أكثِر من التلبية:","listen":"استمع","stop":"إيقاف","ok":"متابعة","guide":"أرشدني","guiding":"جارٍ الإرشاد…","run":"أسرع","day":"نهار","night":"ليل","tour":"الجولة الموجَّهة","mission":"المهمة","of":"من","m":"م","beginSai":"ابدأ السعي","skipTawaf":"تسريع الأشواط المتبقية","skipSai":"تسريع الأشواط المتبقية","wrongWay":"اتجاه خاطئ","wrongWayText":"اجعل الكعبة عن يسارك، واستدر وامشِ في الاتجاه الآخر.","hijr":"هذا الشوط لا يُحتسب","hijrText":"حِجر إسماعيل من الكعبة، فطُف من خارج جداره المقوّس.","green":"الأضواء الخضراء: يُسرع الرجال هنا، وتمشي النساء مشيًا عاديًّا.","doneTitle":"تمّت عمرتك","doneText":"يحلق الرجل رأسه أو يقصّر، وتقصّ المرأة قدر أنملة. تقبّل الله منك.","again":"ابدأ من جديد","back":"العودة إلى الجولة الموجَّهة","entering":"الدخول إلى المسعى…","rabbana":"بين الركن اليماني والحجر الأسود","soundOn":"الصوت مفعّل","soundOff":"الصوت مكتوم","takbir":"عند خط الحجر الأسود","dhikr":"اذكر الله","arriveSafa":"على الصفا","arriveMarwa":"على المروة","noWebgl":"لا يدعم هذا الجهاز العرض ثلاثي الأبعاد (WebGL2 غير متوفر).","how":["الحركة: مفاتيح W A S D أو الأسهم. النظر: اسحب بالفأرة (انقر مرتين لتثبيتها، وEsc لإلغاء ذلك).","على الهاتف: اسحب في اليسار للمشي، وفي اليمين للنظر.","زر «أرشدني» يمشي بك خلال المهمة الحالية ثم يعيد إليك التحكم، وزر «أسرع» يزيد السرعة."]}}},"narration":{"ihram_0":{"en":"Before you reach the Miqat, the boundary where ihram begins, take a full bath and trim your nails. Men may perfume their body, but not their clothes.","ar":"قبل أن تصل إلى الميقات، وهو الحدّ الذي يبدأ منه الإحرام، اغتسل وقلّم أظافرك. ويجوز للرجل أن يتطيّب في بدنه دون ثيابه."},"ihram_1":{"en":"Men wear two white unstitched cloths and sandals. Women wear their usual modest clothes, with the face and hands uncovered.","ar":"يلبس الرجل إزارًا ورداءً أبيضين غير مخيطين، ونعلين. وتلبس المرأة ثيابها المحتشمة المعتادة، مع كشف الوجه والكفّين."},"ihram_2":{"en":"At the Miqat, make your intention for Umrah. If you are flying, the crew announces the Miqat, so be ready before take-off.","ar":"عند الميقات، انوِ العمرة. وإن كنت مسافرًا بالطائرة، فإن الطاقم يعلن عن الميقات، فكن مستعدًّا قبل الإقلاع."},"ihram_3":{"en":"If you fear that illness may stop you, you may add this condition. It is a mercy for older and sick pilgrims.","ar":"إن خشيت أن يمنعك مرض من إتمام العمرة، فلك أن تشترط هذا الشرط. وهو تيسير لكبار السن والمرضى."},"ihram_4":{"en":"Now repeat the Talbiyah often until you reach the Kaaba. Men say it aloud, women softly.","ar":"ثم أكثِر من التلبية حتى تصل إلى الكعبة. يرفع بها الرجال أصواتهم، وتخفضها النساء."},"ihram_5":{"en":"While in ihram, avoid perfume, cutting hair or nails, and marital relations. Men do not cover their head.","ar":"وفي الإحرام اجتنب الطيب، وأخذ شيء من الشعر أو الأظافر، والجماع. ولا يغطّي الرجل رأسه."},"enter_0":{"en":"Every gate of the Haram has a number and a name. Note them down or take a photo before you enter. This is your meeting point if you are separated from your group.","ar":"لكل باب من أبواب الحرم رقم واسم. دوّنهما أو التقط لهما صورة قبل الدخول، فهذا مكان لقائك إن افترقت عن مجموعتك."},"enter_1":{"en":"Enter with your right foot first and say the supplication for entering the mosque.","ar":"ادخل برجلك اليمنى، وقل دعاء دخول المسجد."},"enter_2":{"en":"This is the Kaaba. Take your time. Make any supplication you wish, in your own language.","ar":"هذه هي الكعبة المشرّفة. تمهّل، وادعُ بما شئت، وبلغتك أنت."},"enter_3":{"en":"Zamzam water is available in coolers all around the mosque. Drink and rest whenever you need. Umrah has no time limit.","ar":"ماء زمزم متوفّر في برّادات حول المسجد كله. اشرب واسترح متى احتجت، فليس للعمرة وقت محدّد."},"enter_4":{"en":"Make sure you have wudu before Tawaf. Stop saying the Talbiyah when you begin.","ar":"تأكّد أنك على وضوء قبل الطواف، واقطع التلبية عند بدء الطواف."},"start_0":{"en":"Walk to the corner of the Kaaba with the Black Stone, set in a silver frame. Tawaf starts and ends here.","ar":"توجّه إلى ركن الكعبة الذي فيه الحجر الأسود، في إطاره الفضّي. من هنا يبدأ الطواف وإليه ينتهي."},"start_1":{"en":"Behind you, a green light on the mosque wall marks the starting line. Use it to see where each circuit begins.","ar":"خلفك ضوء أخضر على جدار المسجد يحدّد خطّ البداية. استعن به لتعرف أين يبدأ كل شوط."},"start_2":{"en":"Men uncover the right shoulder for this Tawaf. Face the Black Stone, raise your right hand towards it, and say these words. Do not push to kiss or touch it. Pointing is enough.","ar":"يكشف الرجل كتفه الأيمن في هذا الطواف. استقبل الحجر الأسود، وأشر إليه بيدك اليمنى، وقل هذه الكلمات. ولا تزاحم لتقبيله أو لمسه، فالإشارة تكفي."},"start_3":{"en":"Now walk counter-clockwise, keeping the Kaaba on your left. Men walk briskly in the first three circuits if they are able.","ar":"والآن طُف عكس اتجاه عقارب الساعة، والكعبة عن يسارك. ويُسرع الرجال في الأشواط الثلاثة الأولى إن استطاعوا."},"start_4":{"en":"You will pass the door of the Kaaba, behind a gold-embroidered curtain. There is no fixed supplication for each circuit. Make dua, remember Allah, or recite Quran, in any language.","ar":"ستمرّ بباب الكعبة خلف ستارة مطرّزة بالذهب. ليس لكل شوط دعاء مخصوص، فادعُ واذكر الله أو اقرأ القرآن، بأي لغة."},"start_5":{"en":"Each time you come back to the Black Stone line, one circuit is complete. Tap the counter so you never lose count.","ar":"كلما عدت إلى خط الحجر الأسود اكتمل شوط. اضغط على العدّاد حتى لا يفوتك العدد."},"hijr_0":{"en":"This low, curved wall is the Hijr Ismail. The area inside is part of the Kaaba, so walk around the outside of the wall.","ar":"هذا الجدار المنخفض المقوّس هو حِجر إسماعيل. وما بداخله من الكعبة، فطُف من خارج الجدار."},"hijr_1":{"en":"Above it, the golden waterspout carries rainwater from the roof of the Kaaba.","ar":"وفوقه الميزاب الذهبي الذي ينزل منه ماء المطر من سطح الكعبة."},"hijr_2":{"en":"If you are tired, move towards the outer part of the courtyard or to an upper floor. The circuits are longer, but the crowd is lighter.","ar":"إن شعرت بالتعب، فابتعد نحو أطراف الصحن أو اصعد إلى أحد الطوابق. الأشواط أطول، لكن الزحام أخفّ."},"hijr_3":{"en":"If you lose your group, do not stop or walk against the crowd. Finish your circuit and go to your meeting gate.","ar":"إن فقدت مجموعتك، فلا تتوقّف ولا تمشِ عكس الزحام. أكمل شوطك ثم اذهب إلى باب اللقاء."},"yemeni_0":{"en":"This is the Yemeni Corner, the last corner before the Black Stone. Touch it with your right hand only if it is easy. If you cannot, simply walk on, without pointing.","ar":"هذا هو الركن اليماني، آخر ركن قبل الحجر الأسود. المسه بيدك اليمنى إن تيسّر، وإلا فامضِ دون إشارة."},"yemeni_1":{"en":"Between the Yemeni Corner and the Black Stone, say this verse.","ar":"وبين الركن اليماني والحجر الأسود قل هذه الآية."},"yemeni_2":{"en":"The tall clock tower stands behind this side of the mosque. It helps you find your direction from almost anywhere.","ar":"برج الساعة الشاهق يقع خلف هذه الجهة من المسجد، ويساعدك على معرفة الاتجاه من أي مكان تقريبًا."},"yemeni_3":{"en":"Continue until you complete seven circuits, ending at the Black Stone. Then men cover their right shoulder again.","ar":"أكمل سبعة أشواط تنتهي عند الحجر الأسود، ثم يغطّي الرجال كتفهم الأيمن."},"maqam_0":{"en":"This golden structure is the Maqam Ibrahim, the station of the Prophet Ibrahim. Go behind it and recite this verse.","ar":"هذا البناء الذهبي هو مقام إبراهيم عليه السلام. قف خلفه واقرأ هذه الآية."},"maqam_1":{"en":"Pray two short rak’ahs. It is recommended to recite Al-Kafirun in the first and Al-Ikhlas in the second. If it is crowded, pray anywhere in the mosque.","ar":"صلِّ ركعتين خفيفتين، ويُستحب أن تقرأ في الأولى سورة الكافرون وفي الثانية سورة الإخلاص. وإن كان المكان مزدحمًا فصلِّ في أي مكان من المسجد."},"maqam_2":{"en":"Then drink Zamzam water and ask Allah for whatever you wish.","ar":"ثم اشرب من ماء زمزم، وادعُ الله بما تشاء."},"maqam_3":{"en":"Next comes the Sa’i. Follow the signs to the Mas’a and the hill of Safa.","ar":"بعد ذلك يأتي السعي. اتبع اللوحات المؤدية إلى المسعى وجبل الصفا."},"safa_0":{"en":"This rock is the hill of Safa, where Sa’i begins. As you approach it the first time, recite this.","ar":"هذه الصخرة هي جبل الصفا، ومنه يبدأ السعي. وعند اقترابك منه أول مرة اقرأ هذا."},"safa_1":{"en":"Face the direction of the Kaaba and raise your hands as in supplication. Say Allahu Akbar three times, then these words. Repeat three times, with your own dua in between.","ar":"استقبل جهة الكعبة، وارفع يديك كهيئة الدعاء. كبّر ثلاثًا، ثم قل هذا الذكر. كرّره ثلاث مرات، وادعُ بما شئت بينها."},"safa_2":{"en":"Now walk towards Marwah. Keep to the lane going in your direction and follow the signs above you.","ar":"والآن امشِ نحو المروة. الزم المسار الخاص باتجاهك واتبع اللوحات فوقك."},"safa_3":{"en":"Sa’i does not require wudu, and you may stop to rest. If walking is difficult, you may use a wheelchair.","ar":"لا يُشترط الوضوء للسعي، ويجوز لك أن تستريح. وإن صعب عليك المشي فلك أن تستعمل كرسيًّا متحرّكًا."},"green_0":{"en":"These green lights mark the stretch where Hajar ran in search of water for her son Ismail.","ar":"هذه الأضواء الخضراء تحدّد المسافة التي سعت فيها هاجر بحثًا عن الماء لابنها إسماعيل."},"green_1":{"en":"Men walk quickly between the green lights if they are able. Women walk at their normal pace.","ar":"يُسرع الرجال بين الضوءين الأخضرين إن استطاعوا، وتمشي النساء مشيًا عاديًّا."},"green_2":{"en":"There is no fixed supplication here. Ask Allah for whatever you need, in your own words.","ar":"ليس هنا دعاء مخصوص، فاسأل الله ما تحتاج بكلماتك أنت."},"marwa_0":{"en":"This is Marwah. Reaching it completes one length. Face the Kaaba and repeat the same remembrance as at Safa, without the verse.","ar":"هذه هي المروة. ببلوغها يكتمل شوط واحد. استقبل الكعبة وكرّر الذكر نفسه الذي قلته على الصفا، دون الآية."},"marwa_1":{"en":"Returning to Safa is length two. Seven lengths in total, Safa to Marwah and back, ending here at Marwah.","ar":"والعودة إلى الصفا شوط ثانٍ. والمجموع سبعة أشواط بين الصفا والمروة، تنتهي هنا عند المروة."},"marwa_2":{"en":"Use the counter. Tap once each time you reach a hill.","ar":"استعمل العدّاد، واضغط مرة واحدة كلما بلغت أحد الجبلين."},"done_0":{"en":"Men shave the whole head, which is best, or shorten the hair evenly. Women cut about a fingertip’s length from the end of their hair.","ar":"يحلق الرجل رأسه كله، وهو الأفضل، أو يقصّر شعره من جميع رأسه. وتقصّ المرأة من أطراف شعرها قدر أنملة."},"done_1":{"en":"Your Umrah is complete, and the restrictions of ihram are lifted. May Allah accept it from you.","ar":"وبهذا تمّت عمرتك، وحلّ لك ما كان محظورًا في الإحرام. تقبّل الله منك."},"meaning_niyyah":{"en":"Meaning: Here I am, O Allah, for Umrah."},"meaning_ishtirat":{"en":"Meaning: O Allah, I will leave ihram wherever You hold me back."},"meaning_talbiyah":{"en":"Meaning: Here I am, O Allah, here I am. Here I am, You have no partner, here I am. All praise, all blessings and all sovereignty belong to You. You have no partner."},"meaning_enter":{"en":"Meaning: In the name of Allah, and peace and blessings be upon the Messenger of Allah. O Allah, open for me the gates of Your mercy."},"meaning_bismillah":{"en":"Meaning: In the name of Allah, Allah is the Greatest."},"meaning_rabbana":{"en":"Meaning: Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."},"meaning_maqam":{"en":"Meaning: And take the station of Ibrahim as a place of prayer."},"meaning_safa_verse":{"en":"Meaning: Indeed, Safa and Marwah are among the symbols of Allah. I begin with what Allah began with."},"meaning_safa_dhikr":{"en":"Meaning: There is no god but Allah alone, without partner. His is the dominion and the praise, and He has power over all things. There is no god but Allah alone. He fulfilled His promise, gave victory to His servant, and alone defeated the confederates."}},"views":{"entry":{"kaaba":[0.0,5.6],"black_stone":[-5.6,-0.1],"yemeni":[-6.6,-0.1],"door":[-1.3,4.0],"hijr":[13.3,-0.6],"mizab":[7.0,11.1],"maqam":[1.5,0.0],"start_light":[-58.2,2.9],"clock":[-48.0,51.3],"zamzam":[0.0,-5.9],"gate":[117.3,11.2]},"hijr":{"kaaba":[9.3,16.2],"black_stone":[-8.4,-0.2],"yemeni":[21.5,-0.2],"door":[-9.5,9.2],"hijr":[33.7,-6.3],"mizab":[14.9,43.8],"maqam":[-34.5,0.0],"start_light":[-30.4,1.5],"clock":[43.2,52.8],"zamzam":[-58.0,-1.2],"gate":[-72.7,2.2]},"maqam":{"kaaba":[-3.2,15.0],"black_stone":[-24.9,-0.4],"yemeni":[-17.6,-0.2],"door":[-9.6,14.1],"hijr":[29.1,-1.3],"mizab":[15.3,26.9],"maqam":[-2.4,0.0],"start_light":[-123.4,2.7],"clock":[-52.4,53.0],"zamzam":[-177.5,-2.2],"gate":[166.7,3.3]},"start":{"kaaba":[-1.4,17.4],"black_stone":[0.0,-0.7],"yemeni":[-27.7,-0.3],"door":[12.8,16.8],"hijr":[19.1,-1.2],"mizab":[11.6,26.3],"maqam":[69.7,0.0],"start_light":[-179.2,3.0],"clock":[-87.1,54.0],"zamzam":[128.2,-1.7],"gate":[121.5,2.7]},"yemeni":{"kaaba":[1.5,19.0],"black_stone":[30.0,-0.3],"yemeni":[0.0,-0.8],"door":[19.5,9.8],"hijr":[-20.2,-1.3],"mizab":[-12.4,27.9],"maqam":[27.8,0.0],"start_light":[71.8,1.8],"clock":[179.9,55.3],"zamzam":[42.1,-1.0],"gate":[36.6,1.9]},"green":{"safa_rock":[178.1,0.3],"marwa_rock":[1.4,0.0],"to_marwa":[0.0,0.1],"to_safa":[175.9,0.1],"green_lights":[0.0,25.3],"green_end":[0.0,11.3],"divider":[177.1,-0.9]},"marwa":{"safa_rock":[-179.4,0.1],"marwa_rock":[-12.5,0.0],"to_marwa":[-73.3,2.2],"to_safa":[179.7,0.1],"green_lights":[-177.2,2.9],"green_end":[-177.0,2.2],"divider":[-178.7,-0.2]},"safa":{"safa_rock":[167.5,2.8],"marwa_rock":[0.6,0.0],"to_marwa":[-0.3,0.1],"to_safa":[106.7,2.2],"green_lights":[-0.6,3.2],"green_end":[-0.6,2.1],"divider":[0.9,-0.6]}}};
